-- GearMate v0.3.1: Malaysia Yonex prices and model expansion (checked 2026-10-25).
-- Prerequisite: import database.sql then v03_migration.sql; import THIS file last.
-- Safe to run again: model unique key and model-based price metadata are upserted.
-- Historical user accounts, assessments, and saved configurations are NOT deleted.
USE badminton_gearmate;
CREATE TABLE IF NOT EXISTS racket_market_meta (
  model VARCHAR(150) NOT NULL PRIMARY KEY,
  category ENUM('attack','speed','control') NOT NULL,
  price_tier ENUM('entry','mid','premium') NOT NULL,
  price_rm DECIMAL(10,2) NOT NULL,
  price_source VARCHAR(150) NOT NULL,
  price_url VARCHAR(600) NOT NULL,
  price_checked DATE NOT NULL,
  variant_note VARCHAR(120) NOT NULL DEFAULT '',
  spec_note VARCHAR(255) NOT NULL DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS accessory_market_prices (
  item_code VARCHAR(40) NOT NULL PRIMARY KEY,
  item_type ENUM('string','grip') NOT NULL,
  display_name VARCHAR(150) NOT NULL,
  price_rm DECIMAL(10,2) NOT NULL,
  price_source VARCHAR(150) NOT NULL,
  price_url VARCHAR(600) NOT NULL,
  price_checked DATE NOT NULL,
  note_zh VARCHAR(350) NOT NULL DEFAULT '',
  note_en VARCHAR(350) NOT NULL DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Keep original numeric IDs and recorded user setup references: model is the upsert key.
