INSERT INTO accessory_market_prices (item_code,item_type,display_name,price_rm,price_source,price_url,price_checked,note_zh,note_en) VALUES
 ('BG65', 'string', 'YONEX BG65', 40.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '0.70mm；耐用、线感较柔和。', '0.70mm; durability-oriented, more forgiving feel.'),
 ('BG66UM', 'string', 'YONEX BG66 ULTIMAX', 43.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '0.65mm；偏弹性、击球声清脆，细线需注意耐用性。', '0.65mm; responsive and crisp; thinner gauges may be less durable.'),
 ('BG80', 'string', 'YONEX BG80', 50.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '0.68mm；扎实、偏硬的击球反馈。', '0.68mm; firmer solid hitting feel.'),
 ('BG80P', 'string', 'YONEX BG80 POWER', 50.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '0.68mm；较硬手感与快速反弹取向。', '0.68mm; firm feel and repulsion-focused.'),
 ('EXBOLT63', 'string', 'YONEX EXBOLT 63', 46.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '0.63mm；重视弹性，细线较需要留意耐用性。', '0.63mm; repulsion-focused thin gauge.'),
 ('EXBOLT65', 'string', 'YONEX EXBOLT 65', 48.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '0.65mm；兼顾反弹、控球与耐久取向。', '0.65mm; balances repulsion, control and durability.'),
 ('AEROBITE', 'string', 'YONEX AEROBITE', 50.00, 'Racket Lab', 'https://racketlab.com.my/collections/badminton-strings', '2026-10-25', '主线0.67mm／横线0.61mm；混合线径，偏向控球。', 'Hybrid: 0.67mm main / 0.61mm cross; control-oriented.'),
 ('AC102', 'grip', 'YONEX AC102 SUPER GRAP', 12.00, 'Sports Direct MY', 'https://www.sportsdirect.com.my/yonex/yonex-accessories', '2026-10-25', '单条湿黏手胶；通用防滑手感。', 'Single tacky-feel overgrip.'),
 ('AC149', 'grip', 'YONEX AC149 DRY SUPER GRAP', 16.00, 'Smash Pro', 'https://smashpro78258.store.link/category/grip', '2026-10-25', '干爽型手胶；请向卖家确认单条包装与售价。', 'Dry feel; confirm one-piece packaging and price with seller.'),
 ('AC420', 'grip', 'YONEX AC420 HI SOFT GRAP', 12.00, 'Sports Direct MY', 'https://www.sportsdirect.com.my/yonex/yonex-accessories', '2026-10-25', '较厚、偏缓冲的握把手感。', 'Thicker cushioned grip feel.') ON DUPLICATE KEY UPDATE item_type=VALUES(item_type),display_name=VALUES(display_name),price_rm=VALUES(price_rm),price_source=VALUES(price_source),price_url=VALUES(price_url),price_checked=VALUES(price_checked),note_zh=VALUES(note_zh),note_en=VALUES(note_en);
